def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1

    # Reduce offsets mod n; a residue that appears an even number of times cancels.
    parity = {}
    for d in offsets:
        r = d % n
        parity[r] = parity.get(r, 0) ^ 1
    shifts = [r for r, p in parity.items() if p]

    def rotl(a: int, s: int) -> int:
        # Multiply a by z^s modulo z^n - 1.
        s %= n
        return ((a << s) | (a >> (n - s))) & mask

    def square(a: int) -> int:
        # Over GF(2), (sum a_i z^i)^2 = sum a_i z^(2i); then fold z^n -> 1.
        sq = 0
        for i, c in enumerate(reversed(format(a, 'b'))):
            if c == '1':
                sq |= 1 << (2 * i)
        return (sq & mask) ^ (sq >> n)

    # Compute P^t, where P = sum of z^s over shifts, by left-to-right binary exponentiation.
    poly = 1
    for bit in bin(t)[2:]:
        poly = square(poly)
        if bit == '1':
            acc = 0
            for s in shifts:
                acc ^= rotl(poly, s)
            poly = acc

    # Apply Q(shift) to the state: out_i = XOR over k in Q of x_{(i+k) mod n}.
    x = int(state[::-1], 2)
    out = 0
    for k in range(n):
        if poly >> k & 1:
            out ^= ((x >> k) | (x << (n - k))) & mask

    return format(out, f'0{n}b')[::-1]
